import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with expanded line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
  });
});

test('createInvoice reports CUSTOMER_NOT_FOUND for an unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date formats', () => {
  const testCases = ['2026-10-7', '2026-1-07', '26-10-07', '10-07-2026', 'not-a-date', ''];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  const testCases = ['2026-02-30', '2026-13-01', '2026-00-01', '2026-06-31'];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports NO_LINES for an empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for non-array lines', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  const testCases = [0, -1, 1.5, 'abc', null, undefined];
  for (const qty of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    }), { ok: false, error: 'QTY_INVALID' }, `for qty ${qty}`);
  }
});

test('createInvoice reports UNKNOWN_SKU for a SKU that is not in the catalogue', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 1 }]);
});

test('createInvoice stops at the first error', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 0 }],
  });
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('lineTotal returns qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 50 }), 100);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1 }), 100);
});

test('invoiceTotals calculates subtotal and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500 },
      { qty: 5, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.total, 85000 + 47500);
});

test('invoiceTotals handles a single line', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 12345 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.total, 12345);
});

test('invoiceTotals returns zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with a created invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 10 * 8500 + 5 * 9500);
  assert.equal(totals.total, 10 * 8500 + 5 * 9500);
});

test('addLine adds a new line to a draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);
  const invoice = r1.value;

  const r2 = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine reports QTY_INVALID for invalid quantities', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const testCases = [0, -1, 1.5, 'abc'];
  for (const qty of testCases) {
    assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty }), { ok: false, error: 'QTY_INVALID' }, `for qty ${qty}`);
  }
});

test('addLine reports UNKNOWN_SKU for unknown SKUs', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'NOPE', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r1.value;
  const originalLineCount = original.lines.length;
  const originalQty = original.lines[0].qty;

  addLine(original, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(original.lines.length, originalLineCount);
  assert.equal(original.lines[0].qty, originalQty);
});

test('removeLine removes a line from a draft invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r1.ok, true);

  const r2 = removeLine(r1.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND for non-existent SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'NOPE'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const original = r1.value;
  const originalLineCount = original.lines.length;

  removeLine(original, 'DES-HOUR');

  assert.equal(original.lines.length, originalLineCount);
});

test('issueInvoice sets number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.issueDate, '2026-10-07');
});

test('issueInvoice uses existing numbers to find next', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003'];
  const r2 = issueInvoice(r1.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0004');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r1.value;
  const originalStatus = original.status;

  issueInvoice(original, []);

  assert.equal(original.status, originalStatus);
  assert.equal(original.number, undefined);
});

test('issueInvoice handles different years', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2027-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r1.ok, true);

  const existing = ['INV-2026-0050', 'INV-2027-0010'];
  const r2 = issueInvoice(r1.value, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2027-0011');
});

